/// `PrimaryExpression = Constant | QualifiedName | FunctionCall | ParenthesizedExpression | InlineCast`
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum PrimaryExpression {
    /// A `Constant`.
    Constant(Constant),
    /// A `QualifiedName`.
    QualifiedName(QualifiedName),
    /// A `FunctionCall`.
    FunctionCall(FunctionCall),
    /// A `ParenthesizedExpression`.
    ParenthesizedExpression(ParenthesizedExpression),
    /// A `InlineCast`.
    InlineCast(InlineCast),
}

impl AstNode for PrimaryExpression {
    type Language = Lang;
    fn can_cast(kind: SyntaxKind) -> bool {
        Constant::can_cast(kind)
            || QualifiedName::can_cast(kind)
            || FunctionCall::can_cast(kind)
            || ParenthesizedExpression::can_cast(kind)
            || InlineCast::can_cast(kind)
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let node = match syntax.kind() {
            SyntaxKind::QUALIFIED_NAME => Self::QualifiedName(QualifiedName { syntax }),
            SyntaxKind::FUNCTION_CALL => Self::FunctionCall(FunctionCall { syntax }),
            SyntaxKind::PARENTHESIZED_EXPRESSION => {
                Self::ParenthesizedExpression(ParenthesizedExpression { syntax })
            }
            SyntaxKind::INLINE_CAST => Self::InlineCast(InlineCast { syntax }),
            _ => return Constant::cast(syntax.clone()).map(Self::Constant),
        };
        Some(node)
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::Constant(it) => it.syntax(),
            Self::QualifiedName(it) => it.syntax(),
            Self::FunctionCall(it) => it.syntax(),
            Self::ParenthesizedExpression(it) => it.syntax(),
            Self::InlineCast(it) => it.syntax(),
        }
    }
}

impl From<Constant> for PrimaryExpression {
    fn from(node: Constant) -> Self {
        Self::Constant(node)
    }
}

impl From<QualifiedName> for PrimaryExpression {
    fn from(node: QualifiedName) -> Self {
        Self::QualifiedName(node)
    }
}

impl From<FunctionCall> for PrimaryExpression {
    fn from(node: FunctionCall) -> Self {
        Self::FunctionCall(node)
    }
}

impl From<ParenthesizedExpression> for PrimaryExpression {
    fn from(node: ParenthesizedExpression) -> Self {
        Self::ParenthesizedExpression(node)
    }
}

impl From<InlineCast> for PrimaryExpression {
    fn from(node: InlineCast) -> Self {
        Self::InlineCast(node)
    }
}

